import{c,$ as e,Q as s,j as n,o as a,m as d,g as u}from"./chunks/framework.CWBTDBPu.js";const P=JSON.parse('{"title":"YuVault 插件介绍","description":"","frontmatter":{"title":"YuVault 插件介绍"},"headers":[],"relativePath":"plugins/items/yu-vault/index.md","filePath":"plugins/items/yu-vault/index.md"}'),h={name:"plugins/items/yu-vault/index.md"},p={class:"quick-actions"};function g(y,t,v,m,_,S){const o=e("PluginMeta"),l=e("CopyMarkdownButton"),r=e("CopyLLMButton"),i=e("PluginServerShowcase");return s(),n("div",null,[a(o,{slug:"yu-vault"}),t[0]||(t[0]=d('<h2 id="文档入口" tabindex="-1">文档入口 <a class="header-anchor" href="#文档入口" aria-label="Permalink to &quot;文档入口&quot;">​</a></h2><p>YuVault 是面向 Minecraft <code>1.8.x-1.26.x</code> 的跨版本虚拟保险柜插件，环境适配范围与 YuTeleport 保持一致：Spigot、Paper、Paper 衍生端，以及 Mohist、Arclight、Youer 等 Bukkit API 混合端。它把玩家保险柜、跨服 MySQL 存储、权限动态容量、物品黑白名单和回收箱流程整合到一个轻量 GUI 插件里，适合生存服、模组服、RPG 服和多子服共享背包扩展场景。</p><div class="doc-card-grid"><a class="doc-mini-card" href="install"><strong>安装部署</strong><span>构建、放置 jar、首次启动、运行时依赖、SQLite/MySQL 与上线检查</span></a><a class="doc-mini-card" href="commands"><strong>命令手册</strong><span>/yvault、/yv、/vault 的打开、列表、创建、删除、回收与管理命令</span></a><a class="doc-mini-card" href="config"><strong>配置说明</strong><span>数据库、槽位模式、世界与物品控制、列表 GUI、回收箱和依赖校验</span></a><a class="doc-mini-card" href="permissions"><strong>权限节点</strong><span>玩家基础权限、管理员权限、动态保险柜数量和动态槽位容量</span></a><a class="doc-mini-card" href="api"><strong>插件联动</strong><span>MySQL 跨服、权限插件、菜单插件、世界限制、bStats 与文件结构</span></a><a class="doc-mini-card" href="faq"><strong>常见问题</strong><span>打不开保险柜、权限容量不生效、MySQL 连接、依赖下载和防吞物品排查</span></a></div>',3)),u("div",p,[a(l,{slug:"yu-vault"}),a(r,{slug:"yu-vault"})]),t[1]||(t[1]=d('<h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>广版本与混合端适配</td><td>面向 <code>1.8.x-1.26.x</code>，覆盖 Spigot、Paper、Paper 衍生端，并兼顾 Mohist、Arclight、Youer 等混合端运行环境。</td></tr><tr><td>虚拟保险柜</td><td>玩家可通过命令或 GUI 打开自己的保险柜，管理员可查看、创建、调整和删除他人保险柜。</td></tr><tr><td>SQLite/MySQL 存储</td><td>单服默认使用 SQLite；跨服共享可切换 MySQL，并通过 HikariCP 管理连接池。</td></tr><tr><td>权限动态容量</td><td>支持 <code>yuvault.vaults.&lt;数量&gt;</code> 控制保险柜数量，支持 <code>yuvault.slots.&lt;编号&gt;.&lt;行数&gt;</code> 控制指定保险柜行数。</td></tr><tr><td>命令槽位模式</td><td>可将 <code>slot-mode</code> 切到 <code>command</code>，用 <code>/yvault setslots</code> 固定写入保险柜行数。</td></tr><tr><td>GUI 列表</td><td><code>/yvault gui</code> 展示保险柜列表，支持空状态创建入口、翻页、关闭和返回主菜单命令。</td></tr><tr><td>物品回收箱</td><td>缩小槽位或删除保险柜时，超出物品会进入回收箱，玩家可用 <code>/yvault reclaimed</code> 取回。</td></tr><tr><td>世界与物品控制</td><td>支持世界黑白名单、物品黑白名单和通配符匹配，避免特定世界或高风险物品进入保险柜。</td></tr><tr><td>防吞物品保护</td><td>保存、缩容、删除和反序列化失败时会拒绝覆盖风险数据，并提示管理员查看控制台。</td></tr><tr><td>运行时依赖加载</td><td>首次启动会缓存 HikariCP、SQLite JDBC、MySQL JDBC、SLF4J 等依赖到插件目录并校验哈希。</td></tr><tr><td>统计接入</td><td>内置 bStats Bukkit 统计，插件 ID 为 <code>31043</code>。</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li>构建或获取发布版 <code>YuVault-1.1.0.0-all.jar</code>。</li><li>将 jar 放入服务端 <code>plugins/</code> 目录并启动一次服务器。</li><li>打开 <code>plugins/YuVault/config.yml</code>，确认 <code>storage.type</code>、<code>default-vaults</code>、<code>slot-mode</code> 和世界/物品限制。</li><li>给普通玩家分配 <code>yuvault.use</code>、<code>yuvault.reclaimed</code>，再按需求分配 <code>yuvault.vaults.&lt;数量&gt;</code> 与 <code>yuvault.slots.&lt;编号&gt;.&lt;行数&gt;</code>。</li><li>玩家使用 <code>/vault</code>、<code>/yv</code> 或 <code>/yvault</code> 打开保险柜；使用 <code>/yvault gui</code> 查看保险柜列表。</li><li>修改配置后执行 <code>/yvault reload</code> 重载配置与消息。</li></ol><h2 id="适合的服务器" tabindex="-1">适合的服务器 <a class="header-anchor" href="#适合的服务器" aria-label="Permalink to &quot;适合的服务器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐用法</th></tr></thead><tbody><tr><td>生存服</td><td>给玩家提供额外仓储，使用权限控制默认数量和每个保险柜容量。</td></tr><tr><td>模组服</td><td>配合物品黑名单屏蔽高风险方块、命令方块或特殊 NBT 物品。</td></tr><tr><td>多子服网络</td><td>使用 MySQL 存储，让大厅、生存、资源世界共享同一套保险柜数据。</td></tr><tr><td>RPG 服</td><td>用菜单插件打开 <code>/yvault gui</code>，把保险柜当作角色仓库或会员容量权益。</td></tr><tr><td>强安全服</td><td>保持回收箱和防吞物品保护流程，缩容、删除前先备份数据库。</td></tr></tbody></table><h2 id="当前版本定位" tabindex="-1">当前版本定位 <a class="header-anchor" href="#当前版本定位" aria-label="Permalink to &quot;当前版本定位&quot;">​</a></h2><ul><li>插件版本：<code>1.1.0.0</code></li><li>主类：<code>org.yutay.yuvault.YuVault</code></li><li>主命令：<code>/yvault</code></li><li>别名：<code>/yv</code>、<code>/vault</code></li><li>Java 目标版本：Java 8</li><li>兼容定位：Minecraft <code>1.8.x-1.26.x</code>，Spigot、Paper、Paper 衍生端、Mohist、Arclight、Youer 等混合端</li><li>存储方式：SQLite、MySQL</li><li>bStats 插件 ID：<code>31043</code></li><li>默认配置版本：<code>config-version: 2</code></li><li>默认消息版本：<code>messages-version: 2</code></li></ul><h2 id="使用该插件的服务器" tabindex="-1">使用该插件的服务器 <a class="header-anchor" href="#使用该插件的服务器" aria-label="Permalink to &quot;使用该插件的服务器&quot;">​</a></h2>',9)),a(i,{slug:"yu-vault"})])}const b=c(h,[["render",g]]);export{P as __pageData,b as default};
